mapper.select:
SELECT model.version, model.model_json::text AS model_json, model.content_hash, model.i18n
FROM iot_thing_model model
INNER JOIN iot_product product ON product.id = model.product_id
WHERE product.code = #{productCode}
AND model.version = #{version}
ORDER BY model.version

mapper.update:
UPDATE iot_thing_model model
SET i18n = #{i18n,jdbcType=OTHER}
FROM iot_product product
WHERE product.id = model.product_id
  AND product.code = #{productCode}
  AND model.version = #{version}
